extends Node
class_name TaxiFareDirector

signal objective_changed(text: String)
signal stage_changed(stage_id: String)
signal fare_completed(amount: float)

const STAGES := ["locked", "fuel", "pickup", "dropoff", "complete"]
const PICKUP_RADIUS := 6.5
const DROPOFF_RADIUS := 7.5
const STOP_SPEED_THRESHOLD := 1.25
const GUIDANCE_REFRESH_SECONDS := 0.25
const MIN_FUEL_TO_START := 35.0
const BASE_FARE := 6.0
const FARE_PER_METER := 0.08
const WAIT_FARE_PER_SECOND := 0.025
const WAIT_SPEED_THRESHOLD := 0.8
const MIN_FARE := 10.0
const MAX_FARE := 32.0

var stage := "locked"
var _taxi: ArcadeVehicle
var _fuel_system: FuelPurchaseSystem
var _fuel_station: Node3D
var _passenger: Node3D
var _pickup: Node3D
var _dropoff: Node3D
var _player: PlayerController
var _guidance_elapsed := 0.0
var _planned_distance_m := 0.0
var _fare_amount := 0.0
var _ride_distance_m := 0.0
var _waiting_seconds := 0.0
var _beacon: Node3D
var _beacon_ring: MeshInstance3D
var _beacon_label: Label3D

func configure(taxi: ArcadeVehicle, passenger: Node3D, pickup: Node3D, dropoff: Node3D, player: PlayerController = null, fuel_system: FuelPurchaseSystem = null, fuel_station: Node3D = null) -> void:
    _taxi = taxi
    _fuel_system = fuel_system
    _fuel_station = fuel_station
    _passenger = passenger
    _pickup = pickup
    _dropoff = dropoff
    _player = player
    if _fuel_system != null and not _fuel_system.fuel_purchased.is_connected(_on_fuel_purchased):
        _fuel_system.fuel_purchased.connect(_on_fuel_purchased)
    if _pickup != null and _dropoff != null:
        _planned_distance_m = _pickup.global_position.distance_to(_dropoff.global_position)
    _recompute_meter()
    _build_beacon()
    _sync_visuals()
    _emit_objective()
    set_process(true)

func activate() -> void:
    if stage != "locked":
        return
    _advance("fuel" if GameState.fuel < MIN_FUEL_TO_START else "pickup")
    RuntimeDiagnostics.record_event("taxi_fare_activated", {
        "planned_distance_m": _planned_distance_m,
        "minimum_fare": MIN_FARE,
        "fuel_required": GameState.fuel < MIN_FUEL_TO_START
    })

func _on_fuel_purchased(percent_added: float, cost: float) -> void:
    if stage != "fuel":
        return
    if GameState.fuel < MIN_FUEL_TO_START:
        _emit_objective()
        return
    _advance("pickup")
    RuntimeDiagnostics.record_event("taxi_fare_ready_after_fuel", {
        "percent_added": percent_added,
        "cost": cost,
        "fuel": GameState.fuel
    })

func _process(delta: float) -> void:
    if stage == "locked" or stage == "complete":
        return

    _guidance_elapsed += delta
    if stage == "dropoff" and _taxi != null and _taxi.driver != null:
        _ride_distance_m = maxf(_ride_distance_m, _taxi.trip_distance_m)
        if absf(_taxi.speed) <= WAIT_SPEED_THRESHOLD:
            _waiting_seconds += delta
        _recompute_meter()

    if _taxi != null and _taxi.driver != null:
        if stage == "pickup" and _pickup != null:
            if _taxi.global_position.distance_to(_pickup.global_position) <= PICKUP_RADIUS and _vehicle_is_stopped():
                _pickup_passenger()
                return
        elif stage == "dropoff" and _dropoff != null:
            if _taxi.global_position.distance_to(_dropoff.global_position) <= DROPOFF_RADIUS and _vehicle_is_stopped():
                _complete_fare()
                return

    if _guidance_elapsed >= GUIDANCE_REFRESH_SECONDS:
        _guidance_elapsed = 0.0
        _emit_objective()

func _vehicle_is_stopped() -> bool:
    return _taxi != null and absf(_taxi.speed) <= STOP_SPEED_THRESHOLD

func _pickup_passenger() -> void:
    if stage != "pickup":
        return
    _ride_distance_m = 0.0
    _waiting_seconds = 0.0
    if _taxi != null:
        _taxi.reset_trip_meter()
    _recompute_meter()
    if _passenger != null:
        _passenger.visible = false
    _advance("dropoff")
    RuntimeDiagnostics.record_event("taxi_passenger_picked_up", {
        "vehicle_id": _taxi.vehicle_id if _taxi != null else "",
        "planned_distance_m": _planned_distance_m,
        "pickup_speed_mps": absf(_taxi.speed) if _taxi != null else 0.0
    })

func _complete_fare() -> void:
    if stage != "dropoff":
        return
    _ride_distance_m = maxf(_ride_distance_m, _taxi.trip_distance_m if _taxi != null else 0.0)
    _recompute_meter()
    GameState.add_money(_fare_amount)
    GameState.set_stat("mood", GameState.mood + 4.0)
    if _passenger != null and _dropoff != null:
        _passenger.global_position = _dropoff.global_position + Vector3(2.0, 0.0, 0.0)
        _passenger.visible = true
    _advance("complete")
    fare_completed.emit(_fare_amount)
    RuntimeDiagnostics.record_event("taxi_fare_completed", {
        "fare": _fare_amount,
        "planned_distance_m": _planned_distance_m,
        "ride_distance_m": _ride_distance_m,
        "waiting_seconds": _waiting_seconds,
        "vehicle_id": _taxi.vehicle_id if _taxi != null else ""
    })

func _recompute_meter() -> void:
    var metered := BASE_FARE + _ride_distance_m * FARE_PER_METER + _waiting_seconds * WAIT_FARE_PER_SECOND
    _fare_amount = clampf(metered, MIN_FARE, MAX_FARE)

func _advance(next_stage: String) -> void:
    if not STAGES.has(next_stage):
        return
    stage = next_stage
    stage_changed.emit(stage)
    _sync_visuals()
    _emit_objective()
    RuntimeDiagnostics.record_event("taxi_fare_stage", {"stage": stage})

func current_objective() -> String:
    var text := _objective_text()
    var target := _target_for_stage()
    var actor := _guidance_actor()
    if target != null and actor != null and stage != "locked" and stage != "complete":
        text += " · %d م" % int(round(actor.global_position.distance_to(target.global_position)))
    return text

func _objective_text() -> String:
    match stage:
        "locked": return ""
        "fuel": return "TAXI RUN · عبّي إيصنص قبل المشوار"
        "pickup":
            if _taxi != null and _taxi.driver != null and _pickup != null and _taxi.global_position.distance_to(_pickup.global_position) <= PICKUP_RADIUS and not _vehicle_is_stopped():
                return "TAXI RUN · قف بجانب الراكب ليركب"
            return "TAXI RUN · خذ الراكب من محطة باب عليوة"
        "dropoff":
            if _taxi != null and _taxi.driver != null and _dropoff != null and _taxi.global_position.distance_to(_dropoff.global_position) <= DROPOFF_RADIUS and not _vehicle_is_stopped():
                return "TAXI RUN · قف عند باب البحر لإنزال الراكب · العداد %.1f د.ت" % _fare_amount
            return "TAXI RUN · باب البحر · العداد %.1f د.ت · %d م" % [_fare_amount, int(round(_ride_distance_m))]
        "complete": return "TAXI RUN · تم المشوار · قبضت %.1f د.ت" % _fare_amount
        _: return ""

func _emit_objective() -> void:
    objective_changed.emit(current_objective())

func serialize_runtime() -> Dictionary:
    return {
        "stage": stage,
        "ride_distance_m": _ride_distance_m,
        "waiting_seconds": _waiting_seconds
    }

func restore_runtime(data: Dictionary) -> void:
    var candidate := str(data.get("stage", "locked"))
    stage = candidate if STAGES.has(candidate) else "locked"
    _ride_distance_m = _safe_meter_value(data.get("ride_distance_m", 0.0), 100000.0)
    _waiting_seconds = _safe_meter_value(data.get("waiting_seconds", 0.0), 7200.0)
    _recompute_meter()
    if stage == "dropoff":
        if _passenger != null:
            _passenger.visible = false
        if _taxi != null:
            _taxi.trip_distance_m = _ride_distance_m
    elif _passenger != null:
        _passenger.visible = stage != "locked"
        if stage == "complete" and _dropoff != null:
            _passenger.global_position = _dropoff.global_position + Vector3(2.0, 0.0, 0.0)
    _sync_visuals()
    _emit_objective()

func _safe_meter_value(value, maximum: float) -> float:
    var parsed := float(value)
    if is_nan(parsed) or is_inf(parsed):
        return 0.0
    return clampf(parsed, 0.0, maximum)

func _target_for_stage() -> Node3D:
    match stage:
        "fuel": return _fuel_station
        "pickup": return _pickup
        "dropoff": return _dropoff
        _: return null

func _guidance_actor() -> Node3D:
    if _taxi != null and _taxi.driver != null:
        return _taxi
    return _player

func _build_beacon() -> void:
    if _beacon != null:
        return
    _beacon = Node3D.new()
    _beacon.name = "TaxiFareObjectiveBeacon"
    add_child(_beacon)

    _beacon_ring = MeshInstance3D.new()
    var torus := TorusMesh.new()
    torus.inner_radius = 1.55
    torus.outer_radius = 1.95
    _beacon_ring.mesh = torus
    _beacon_ring.rotation_degrees.x = 90.0
    var material := StandardMaterial3D.new()
    material.albedo_color = Color("#44d7b6")
    material.emission_enabled = true
    material.emission = Color("#126654")
    material.emission_energy_multiplier = 1.8
    _beacon_ring.material_override = material
    _beacon.add_child(_beacon_ring)

    _beacon_label = Label3D.new()
    _beacon_label.text = "TAXI RUN"
    _beacon_label.position = Vector3(0, 2.5, 0)
    _beacon_label.font_size = 52
    _beacon_label.pixel_size = 0.006
    _beacon_label.outline_size = 10
    _beacon_label.billboard = BaseMaterial3D.BILLBOARD_ENABLED
    _beacon.add_child(_beacon_label)

func _sync_visuals() -> void:
    if _beacon != null:
        var target := _target_for_stage()
        _beacon.visible = target != null
        if target != null:
            _beacon.global_position = target.global_position + Vector3(0, 0.25, 0)
    if _passenger != null:
        if stage == "locked":
            _passenger.visible = false
        elif stage == "pickup":
            _passenger.visible = true
            if _pickup != null:
                _passenger.global_position = _pickup.global_position + Vector3(0.0, 0.0, 1.5)
        elif stage == "dropoff":
            _passenger.visible = false
        elif stage == "complete" and _dropoff != null:
            _passenger.visible = true
            _passenger.global_position = _dropoff.global_position + Vector3(2.0, 0.0, 0.0)

extends Interactable
class_name VerticalSliceCheckpoint

@export var checkpoint_id := "checkpoint"

func _ready() -> void:
    add_to_group("interactable")
    add_to_group("vertical_slice_checkpoint")

func interact(actor: Node) -> void:
    if not can_interact(actor):
        return
    interacted.emit(actor)
